+                return true;
+            }
+        }
+
+        private static boolean isIdle(long value) {
+            // the parity of the value indicates the idle state: initially zero (idle), so active == odd
+            return (value & 1) == 0;
+        }
+    }
+
+    public void run(Settings settings, ThreadPool threadPool, Lifecycle lifecycle) {
