+    /**
+     * Asserts that {@link ValuesSourceReaderOperator#status} claims that only
+     * the expected readers are built after loading non-singleton pages.
+     */
+    public void testLoadAllStatusAllInOnePage() {
+        testLoadAllStatus(true);
